import{_ as t,o as s,c as a,a2 as n}from"./chunks/framework.Zh78JZbW.js";const m=JSON.parse('{"title":"Glossaire","description":"","frontmatter":{},"headers":[],"relativePath":"guide/lexique.md","filePath":"guide/lexique.md"}'),r={name:"guide/lexique.md"};function d(o,e,i,l,c,u){return s(),a("div",null,[...e[0]||(e[0]=[n(`<h1 id="glossaire" tabindex="-1">Glossaire <a class="header-anchor" href="#glossaire" aria-label="Permalink to &quot;Glossaire&quot;">​</a></h1><p>Une instance regroupe une version de Minecraft, un loader et des mods, dans un dossier qui lui est propre : vous pouvez en créer plusieurs, elles restent indépendantes les unes des autres.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Kodus</span></span>
<span class="line"><span>├── Survie          1.21 · Fabric    Sodium, Iris… + shaders, resource packs</span></span>
<span class="line"><span>├── Modpack         1.20.1 · Forge   Create, JEI… (importé d&#39;un .kpack)</span></span>
<span class="line"><span>└── Créatif         1.21 · Vanilla   aucun mod, resource packs</span></span></code></pre></div><p>Un mod installé dans une instance n&#39;apparaît pas dans les autres : vous pouvez ainsi tester des mods sans risque dans une copie.</p><table tabindex="0"><thead><tr><th>Terme</th><th>Définition</th></tr></thead><tbody><tr><td>Instance</td><td>Une installation de Minecraft avec ses propres réglages, mods et mondes. Exemple : une instance Survie en 1.21 avec Fabric et une instance Créatif en Vanilla.</td></tr><tr><td>Version</td><td>La version de Minecraft (1.20.1, 1.21…). Un mod est conçu pour une version précise : un mod 1.20.1 ne fonctionne pas en 1.21.</td></tr><tr><td>Vanilla</td><td>Minecraft dans sa version d&#39;origine, sans mods.</td></tr><tr><td>Loader</td><td>Le composant qui permet de charger les mods. Un mod est conçu pour un loader : un mod Fabric ne fonctionne pas avec Forge.</td></tr><tr><td>Fabric / Quilt</td><td>Loaders légers et performants, privilégiés pour les mods d&#39;optimisation (Sodium…). Quilt est compatible avec la plupart des mods Fabric.</td></tr><tr><td>Forge / NeoForge</td><td>Loaders des mods et modpacks d&#39;envergure (Create, technologie, magie…). NeoForge succède à Forge pour les versions récentes.</td></tr><tr><td>Mod</td><td>Un ajout au jeu : contenu, interface, performances. Il est stocké dans le dossier <code>mods</code> de l&#39;instance.</td></tr><tr><td>Dépendance</td><td>Un mod requis par un autre pour fonctionner (souvent Fabric API). Kodus installe les dépendances automatiquement.</td></tr><tr><td>Resource pack</td><td>Modifie les textures, les sons ou les modèles, sans changer le gameplay. Fonctionne également en Vanilla.</td></tr><tr><td>Shader</td><td>Améliore l&#39;éclairage, les ombres et l&#39;eau. Nécessite un ordinateur suffisamment puissant et le mod Iris.</td></tr><tr><td>Datapack</td><td>Modifie les règles d&#39;un monde (recettes, génération…), sans mod. Il s&#39;installe dans un monde précis.</td></tr><tr><td>Modpack</td><td>Une instance prête à l&#39;emploi (mods et réglages), partagée sous forme d&#39;un fichier unique : <code>.kpack</code> pour Kodus, <code>.mrpack</code> pour Modrinth.</td></tr><tr><td>Modrinth</td><td>La plateforme depuis laquelle Kodus télécharge les mods, packs et shaders.</td></tr></tbody></table>`,5)])])}const g=t(r,[["render",d]]);export{m as __pageData,g as default};
